-- =============================================================================
-- 0051_mode_hours.sql
--
-- GENERATED by scripts/build-mode-hours.mjs. Do not hand-edit.
--
-- A rite may say at what hour each of its modes applies, so the picker can open
-- on the sitting you are actually in rather than always on the morning.
--
-- A COLUMN, NOT THREE STRINGS IN THE CLIENT. The obvious implementation is a
-- map from hour to pratah/madhyahnika/sayam in PoojaViewer -- which is exactly
-- what 0047 took out. Those names belong to this rite, the next nitya karma
-- will have its own, and a component that knows them must be edited every time
-- a rite is added.
--
-- THE READER'S CLOCK, NOT THE SUN. Sunrise and solar noon move by weeks across
-- the year and would need the place, the date and an almanac -- and the rite
-- deliberately asks for none of those. The book's own sunset-dependent
-- instruction, facing west before sunset and east after, is printed as a
-- sentence for the reader to judge, because no clock can answer it. A picker
-- needs only a sensible opening guess that one tap corrects.
--
-- NULL MEANS DO NOT GUESS. Ganesha and Varalakshmi have days, not hours: there
-- is no time at which a Punar Pooja becomes the right answer. Their rows stay
-- null and the picker leaves them alone.
-- =============================================================================

begin;

alter table public.pooja_modes
  add column if not exists from_hour integer;

do $$ begin
  alter table public.pooja_modes
    add constraint pooja_modes_from_hour_ck check (from_hour between 0 and 23);
exception when duplicate_object or duplicate_table then null; end $$;

comment on column public.pooja_modes.from_hour is
  'Local hour at which this mode becomes the current one, until the next begins. Null means the mode is not chosen by the clock -- a multi-day observance has days, not hours. A pooja that sets it on any mode must cover hour 0, or some hour has no answer.';

update public.pooja_modes set from_hour = 0, updated_at = now()
 where pooja_id = 'sandhyavandanam' and mode = 'pratah';
update public.pooja_modes set from_hour = 11, updated_at = now()
 where pooja_id = 'sandhyavandanam' and mode = 'madhyahnika';
update public.pooja_modes set from_hour = 16, updated_at = now()
 where pooja_id = 'sandhyavandanam' and mode = 'sayam';

-- --- assert ------------------------------------------------------------------
do $$
declare n int; r record;
begin
  select count(*) into n from public.pooja_modes where pooja_id = 'sandhyavandanam' and from_hour is not null;
  if n <> 3 then raise exception 'sandhyavandanam has % clock-tagged modes, expected 3', n; end if;

  -- Whatever the hour, exactly one mode answers for it. Checked by walking all
  -- twenty-four rather than trusting the three boundaries: an off-by-one at a
  -- boundary is precisely the fault that would leave an hour unanswered, and it
  -- would not show up in a count.
  for r in select distinct pooja_id from public.pooja_modes where from_hour is not null loop
    for n in 0..23 loop
      if not exists (
        select 1 from public.pooja_modes m
         where m.pooja_id = r.pooja_id and m.from_hour is not null and m.from_hour <= n
      ) then
        raise exception 'no mode of % answers for hour %', r.pooja_id, n;
      end if;
    end loop;
  end loop;

  -- A pooja with days must not have hours. Ganesha at 11:00 is not a Punar Pooja.
  select count(*) into n from public.pooja_modes m
    join public.poojas p on p.id = m.pooja_id
   where m.from_hour is not null and p.ritual_class is distinct from 'nitya';
  if n > 0 then raise exception '% non-nitya mode(s) carry an hour', n; end if;

  -- Every clock-tagged mode still has steps, or the picker would open on an
  -- empty list at that hour. 0047 checks this for modes generally; the clock
  -- makes it sharper, because here the app chooses the mode rather than the
  -- reader.
  select count(*) into n from public.pooja_modes m
   where m.from_hour is not null
     and not exists (
       select 1 from public.pooja_steps s
        where s.pooja_id = m.pooja_id and m.mode = any(s.modes)
     );
  if n > 0 then raise exception '% clock-tagged mode(s) have no steps', n; end if;
end $$;


-- Carriage returns, from pasting this file into a browser SQL editor. See
-- scripts/_migration.mjs.
do $$
declare
  r record;
  n bigint;
begin
  for r in
    select c.table_name, c.column_name
      from information_schema.columns c
      join information_schema.tables t
        on t.table_schema = c.table_schema and t.table_name = c.table_name
     where c.table_schema = 'public'
       and t.table_type = 'BASE TABLE'
       and c.data_type in ('text', 'character varying', 'character')
  loop
    execute format(
      'update public.%I set %I = replace(%I, chr(13), %L)'
      || ' where position(chr(13) in %I) > 0',
      r.table_name, r.column_name, r.column_name, '', r.column_name
    );
    get diagnostics n = row_count;
    if n > 0 then
      raise notice 'stripped CR from % row(s) of %.%', n, r.table_name, r.column_name;
    end if;
  end loop;
end $$;

commit;
